steps = [
    step("先看哪些客户端会被 Envoy 拒绝(Envoy 要求客户端证书,服务端证书由 CA1 签发,信任 CA1 和 CA2)。带 CA1 签发的有效证书:成功,HTTP 200。不带证书:失败,tlsv13 alert certificate required。带 CA2 签发的有效证书:成功。带未知 CA3 签发的证书:失败,tlsv1 alert unknown ca。带已经过期的证书(有效期 1 s,握手前已过期):失败,alert certificate expired。客户端不信任服务端的 CA:失败,certificate verify failed: unable to get local issuer certificate。每次握手只要 1~5 ms,失败也是立刻的,不是超时。", t=tl(S(1)), mark=lidx(S(1), '(b)不带客户端证书', '(d)未知 CA3', '(e)已经过期'), done=lidx(S(1), '(a)CA1 签发的有效', '(c)CA2 签发的有效'), b=bars([['有效证书 CA1 成功', 1, '成功'], ['有效证书 CA2 成功', 1, '成功'], ['不带证书', 0, '失败'], ['未知 CA3', 0, '失败'], ['过期证书', 0, '失败'], ['客户端不信服务端 CA', 0, '失败']], 1, done=[0, 1], mark=[2, 3, 4, 5]), kv=KV([['不带证书', 'certificate required'], ['未知 CA', 'unknown ca'], ['过期', 'certificate expired'], ['CA2 签发', '被信任,成功']], ['未知 CA'])),
    step("服务端证书轮换。客户端每 20 ms 做一次完整握手加一个请求,共 199 次握手,第 2 s 原子替换 SDS 文件(写临时文件再 rename),换成新签发的证书(新密钥、新序列号)。结果失败 0 次;替换文件在 2.00 s,客户端第一次看到新证书在 2.03 s,相差 30 ms;之后再没有看到旧证书。这次只测了新握手,没有测已经建立的长连接,没有验证长连接在轮换之后是否继续使用旧证书。", t=tl(S(2)), mark=lidx(S(2), '共 '), done=lidx(S(2), '原子替换 SDS 文件之后'), b=bars([['握手次数', 199, '199'], ['失败次数', 0, '0'], ['看到新证书的延迟 ms', 30, '30'], ['新证书后又看到旧证书', 0, '0']], 199, done=[1, 3], cur=[0], mark=[2]), kv=KV([['握手', '199 次,失败 0'], ['生效延迟', '30 ms'], ['替换方式', '写临时文件再 rename'], ['长连接', '没有验证']], ['生效延迟'])),
    step("证书过期之后。服务端证书有效期只有 5 s,客户端每 200 ms 握手一次。旧证书在 0.0~4.5 s 成功 22 次;4.7~7.8 s 失败 16 次,错误是 certificate has expired;第 8.0 s 换成新的 1 小时证书,第一次成功在 8.0 s。失败是客户端验证服务端证书时报的,说明 Envoy 在证书过期之后仍然把这张证书发给了客户端,没有自己撤下。过期的窗口从到期一直延续到轮换完成,期间所有新握手都失败。", t=tl(S(3)), mark=lidx(S(3), 'Envoy 在证书过期之后'), done=lidx(S(3), '旧证书(有效期 5 s)'), b=bars([['到期前成功的握手', 22, '22'], ['到期后失败的握手', 16, '16'], ['过期窗口 s(7.8 减 4.7 再加一个间隔)', 3.3, '约 3.3(4.7~8.0)']], 22, done=[0], mark=[1, 2]), kv=KV([['证书有效期', '5 s'], ['过期后', '16 次失败,certificate has expired'], ['恢复', '第 8.0 s 轮换后立刻成功'], ['Envoy 行为', '过期后仍提供原证书']], ['过期后'])),
    step("CA 轮换的顺序。五种组合:(a)信任 CA1,服务端证书 CA1:成功。(b)信任 CA1,服务端证书 CA2(服务端先换):失败,unable to get local issuer certificate。(c)信任 CA1 加 CA2,服务端证书 CA2(先分发信任包):成功。(d)信任 CA2,服务端证书 CA1(客户端先去掉了 CA1):失败。(e)信任 CA2,服务端证书 CA2:成功。信任包要先于证书发出去,旧 CA 要在所有证书都换完之后才能去掉:分发新旧两个 CA 的信任包,换签发者,再去掉旧 CA,每一步要等上一步在所有实例上完成。", t=tl(S(4)), mark=lidx(S(4), '(b)信任 CA1,服务端证书 CA2', '(d)信任 CA2,服务端证书 CA1'), done=lidx(S(4), '(a)信任 CA1,服务端证书 CA1', '(c)信任 CA1+CA2', '(e)信任 CA2,服务端证书 CA2'), b=bars([['(a)旧信任包 + 旧证书', 1, '成功'], ['(b)旧信任包 + 新证书', 0, '失败'], ['(c)新旧信任包 + 新证书', 1, '成功'], ['(d)新信任包 + 旧证书', 0, '失败'], ['(e)新信任包 + 新证书', 1, '成功']], 1, done=[0, 2, 4], mark=[1, 3]), kv=KV([['第一步', '分发新旧两个 CA 的信任包'], ['第二步', '服务端证书换成新 CA 签发'], ['第三步', '信任包里去掉旧 CA'], ['顺序错', '握手立刻失败']], ['第一步'])),
]
